/**
 * PAPER, FROM A REAL SHEET
 *
 * Cut from a supplied photograph of an old delivery docket: a coffee ring and a
 * splash. The image was a staged still life with
 * type and handwriting on it, so it could not be tiled whole; these three are the
 * parts that could be lifted clean. Its cream card was too smooth to beat the
 * generated grain, which stays, and its torn edge runs over a ruled pad in the
 * same colours as its own fibres — three tracings could not separate them, so
 * it was left out rather than shipped ragged in the wrong way.
 *
 * The stains are MULTIPLY MAPS — each pixel is the stain divided by the paper
 * under it, so white means "no change" and they lay onto any stock without an
 * alpha channel. Coffee is orange-brown, so that is all that survives: the type
 * through the ring is grey and the legal pad under the splash is yellow, and
 * both drop out — bar one coffee-stained "52" on the ring's lower arc, lifted
 * out by hand, which leaves the ring a break the way real ones have.
 *
 * Injected as custom properties at startup (index.tsx) so the stylesheet can
 * place them without carrying the blobs.
 */
export const PAPER_DECALS: Record<string, string> = {
  '--decal-ring': 'data:image/webp;base64,',
  '--decal-splash': 'data:image/webp;base64,',
};

/**
 * THE STOCK'S OWN WEAVE.
 *
 * A photographed linen with its tone divided out — only the high frequency is
 * kept, centred on white, so it MULTIPLIES onto a card as a weave and never as
 * a shade. Cross-faded at the seams: a 512px tile with a visible grid is worse
 * than no tile at all.
 */
export const LINEN = "data:image/webp;base64,";

/**
 * THE ROOM'S OWN BOARDS.
 *
 * The supplied oak planks with their tone divided out, like the linen: only the
 * grain survives, centred on mid-grey, so it SOFT-LIGHTS onto the dark frames
 * and never repaints them. The planks as photographed are too dark and flat to
 * show on a dark rail at all — measured std 2.9 of 255, and WebP smoothed that
 * to a 1 KB flat colour. The top and bottom are folded together so it tiles.
 * The second supplied wood, a woven parquet, is not used.
 */
export const OAK = 'data:image/webp;base64,';

/**
 * LEATHER, FOR THE BOUND THINGS.
 *
 * The supplied hide, treated exactly like the oak: tone divided out, grain only,
 * all four edges folded and lifted with a wrap-around blur so it tiles. It goes
 * on the Codex, which is a bound book, and on the underground shelf, which is
 * the one place in the game that is not a workshop.
 */
export const LEATHER = 'data:image/webp;base64,';
